class Solution { public int shortestTour(int[][] c) { int n=c.length,N=1<<n,inf=1000000000;int[][]d=new int[N][n];for(int[]r:d)Arrays.fill(r,inf);d[1][0]=0;for(int m=1;m<N;m++)if((m&1)!=0)for(int u=0;u<n;u++)if(d[m][u]<inf)for(int v=0;v<n;v++)if((m&(1<<v))==0)d[m|1<<v][v]=Math.min(d[m|1<<v][v],d[m][u]+c[u][v]);int best=inf;for(int u=0;u<n;u++)best=Math.min(best,d[N-1][u]+c[u][0]);return best;} }
